60	// so a "result" and a "state" entry can be compared field for field. Key order
61	// is irrelevant to the comparison; key presence (e.g. an omitted nextRetry) and
62	// every value still count, so a field set in only one path fails the match.
63	func canonicalJSON(t *testing.T, body []byte) string {
64		t.Helper()
65		var m map[string]any
66		if err := json.Unmarshal(body, &m); err != nil {
67			t.Fatal(err)
68		}
69		m["t"] = "<kind>"
70		b, err := json.Marshal(m)
