77	// TestSavePathParityNormalVsCompaction pins the consolidation: the ordinary
78	// incremental save path and the automatic-compaction snapshot path must encode
79	// the same message record identically. For every message the two paths' submit
80	// entries are byte-identical, and the snapshot's status entry matches the
81	// ordinary path's last result entry for that message field for field (only the
82	// record kind tag differs), across success, a three-attempt waiting record with
83	// its retry schedule, replay attributed to a raw-bytes winner, expiry and
84	// unknown-source — and across invalid-UTF-8 id, destination, payload and reason
85	// bytes, plus an empty payload.
86	func TestSavePathParityNormalVsCompaction(t *testing.T) {
87		idFF := string([]byte{0xFF})
88		idFE := string([]byte{0xFE})
89		rawTo := "t\xffo"
90	
91		dir := t.TempDir()
92		q, err := Open(dir)
