115			Payload: "", ProofAt: 500}})
116		// replay naming the raw-bytes winner idFF
117		submit(Envelope{Message: Message{ID: "loser", From: "a", To: rawTo, Nonce: 50,
118			Payload: "plain", ProofAt: 100}})
