187				var e logEntry
188				if err := json.Unmarshal(body, &e); err != nil {
189					t.Fatal(err)
190				}
191				if e.T == wantKind {
192					m[decodedID(t, body)] = body
193				}
194			}
195			return m
196		}
197	
198		normalSubmits := submitByID(normalEntries)
199		compactedSubmits := submitByID(compactedEntries)
200		normalResults := lastStatusByID(normalEntries, kindResult)
201		compactedStates := lastStatusByID(compactedEntries, kindState)
202	
203		wantIDs := []string{idFF, idFE, "loser", "alien", "exp", "empt", "pend"}
204		if len(normalSubmits) != len(wantIDs) || len(compactedSubmits) != len(wantIDs) {
205			t.Fatalf("submit entry count: normal=%d compact=%d want=%d",
206				len(normalSubmits), len(compactedSubmits), len(wantIDs))
207		}
208		for _, id := range wantIDs {
209			ns, okN := normalSubmits[id]
210			cs, okC := compactedSubmits[id]
211			if !okN || !okC {
212				t.Fatalf("submit entry missing for id % x: normal=%v compact=%v", id, okN, okC)
213			}
214			// The submit frame restores original content and submission order; the
215			// two paths must write it byte for byte.
216			if !bytes.Equal(ns, cs) {
217				t.Fatalf("submit entry differs by path for id % x:\nnormal   %s\ncompact  %s", id, ns, cs)
218			}
219		}
220	
221		// Every processed message has a last result on the normal path and exactly
222		// one state in the snapshot; the pending message has neither.
223		processed := []string{idFF, idFE, "loser", "alien", "exp", "empt"}
224		if len(normalResults) != len(processed) {
225			t.Fatalf("want %d last-result entries, got %d", len(processed), len(normalResults))
226		}
227		if len(compactedStates) != len(processed) {
228			t.Fatalf("want %d compacted state entries, got %d", len(processed), len(compactedStates))
229		}
230		for _, id := range processed {
231			nr, okN := normalResults[id]
232			cs, okC := compactedStates[id]
233			if !okN || !okC {
234				t.Fatalf("status entry missing for id % x: result=%v state=%v", id, okN, okC)
235			}
236			if got, want := canonicalJSON(t, nr), canonicalJSON(t, cs); got != want {
237				t.Fatalf("status entry differs by path for id % x:\nresult %s\nstate  %s", id, got, want)
238			}
239		}
240		if _, pending := normalResults["pend"]; pending {
241			t.Fatal("pending message must have no result entry")
242		}
243		if _, pending := compactedStates["pend"]; pending {
244			t.Fatal("compaction must not manufacture an attempt for a pending message")
245		}
246	
247		// The snapshot still carries invalid bytes base64-encoded, never as the
248		// Unicode replacement character, and keeps the empty payload plain.
249		raw, err := os.ReadFile(filepath.Join(dir, logName))
250		if err != nil {
251			t.Fatal(err)
252		}
253		for _, marker := range []string{`"idB64":"`, `"toB64":"`, `"payloadB64":"`, `"reasonB64":"`, `"consumeToB64":"`} {
254			if !bytes.Contains(raw, []byte(marker)) {
255				t.Fatalf("compacted log missing raw-bytes marker %s", marker)
256			}
257		}
258		if bytes.Contains(raw, []byte(replacementCharID)) {
259			// Only a genuinely invalid-byte value would surface here; none of the
260			// content uses the legal U+FFFD, so its presence means a rewrite.
261			t.Fatalf("compacted log rewrote invalid bytes to U+FFFD")
262		}
263	}
