1	package main
2	
3	import (
4		"encoding/json"
5		"io"
6		"strconv"
7		"strings"
8		"testing"
9	)
10	
11	// These tests pin the command-line observable behaviour of re-using a message
12	// id at submit time, end to end through the real binary and a fresh on-disk
13	// state directory per scenario:
14	//
15	//   - the same id with identical content returns the existing record (whether
16	//     it is still pending or already waiting), prints no second entry and keeps
17	//     the original submission position;
18	//   - the same id on a non-terminal record with ANY different content field
19	//     exits 13 as a message-content conflict, prints no success record and
20	//     changes neither the original record nor sibling messages;
21	//   - a terminal (delivered) id can never be submitted again: identical and
22	//     different content alike exit 14, never 13, and advancing time again must
23	//     not redeliver it.
24	//
25	// All processing time is supplied explicitly in Unix milliseconds, so every
26	// result is deterministic and reproducible offline with no chain or service.
27	
28	// cliSubmitSpec is one `queue submit` invocation. Payload and expiry can be
29	// omitted from the argv entirely to exercise the CLI defaults (empty payload,
30	// expiry 0 = never), which must be equivalent to passing the same values.
31	type cliSubmitSpec struct {
32		id          string
33		from        string
34		to          string
35		payload     string
36		nonce       uint64
37		proofAt     int64
38		expiresAt   int64
39		omitPayload bool
40		omitExpires bool
41	}
42	
43	func submitRaw(t *testing.T, state string, s cliSubmitSpec) cliResult {
44		t.Helper()
45		args := []string{
46			"--id", s.id, "--from", s.from, "--to", s.to,
47			"--nonce", strconv.FormatUint(s.nonce, 10),
48			"--proof-at", strconv.FormatInt(s.proofAt, 10),
49		}
50		if !s.omitPayload {
51			args = append(args, "--payload", s.payload)
52		}
53		if !s.omitExpires {
54			args = append(args, "--expires-at", strconv.FormatInt(s.expiresAt, 10))
55		}
56		return queueCLI(t, state, "submit", args...)
57	}
58	
59	// cliSubmitRecord is the JSON object printed by a successful submit. Absent
60	// nextRetryMs/expiresAtMs fields decode as zero, matching the omitempty output
61	// of pending records and never-expiring messages.
62	type cliSubmitRecord struct {
63		ID        string `json:"id"`
64		Status    string `json:"status"`
65		Reason    string `json:"reason"`
66		Attempts  int    `json:"attempts"`
67		NextRetry int64  `json:"nextRetryMs"`
68		ExpiresAt int64  `json:"expiresAtMs"`
69	}
70	
71	func mustSubmit(t *testing.T, state string, s cliSubmitSpec) (cliSubmitRecord, string) {
72		t.Helper()
73		r := submitRaw(t, state, s)
74		if r.code != 0 {
75			t.Fatalf("submit %s: exit=%d stderr=%q", s.id, r.code, r.stderr)
76		}
77		var rec cliSubmitRecord
78		if err := json.Unmarshal([]byte(strings.TrimSpace(r.stdout)), &rec); err != nil {
79			t.Fatalf("decode submit output %q: %v", r.stdout, err)
80		}
81		return rec, r.stdout
82	}
83	
84	// cliFullRecord is the per-id query JSON view with every message-content field.
85	type cliFullRecord struct {
86		ID        string `json:"id"`
87		From      string `json:"from"`
88		To        string `json:"to"`
89		Nonce     uint64 `json:"nonce"`
90		Payload   string `json:"payload"`
91		ProofAt   int64  `json:"proofAtHeight"`
92		ExpiresAt int64  `json:"expiresAtMs"`
93		Status    string `json:"status"`
94		Reason    string `json:"reason"`
95		Attempts  int    `json:"attempts"`
96		NextRetry int64  `json:"nextRetryMs"`
97	}
98	
99	func queryFull(t *testing.T, state, id string) cliFullRecord {
100		t.Helper()
101		r := queueCLI(t, state, "query", "--id", id)
102		if r.code != 0 {
103			t.Fatalf("query %s: exit=%d stderr=%q", id, r.code, r.stderr)
104		}
105		var rec cliFullRecord
106		if err := json.Unmarshal([]byte(strings.TrimSpace(r.stdout)), &rec); err != nil {
107			t.Fatalf("decode query output %q: %v", r.stdout, err)
108		}
109		return rec
110	}
111	
112	// queryAll reads the whole listing (one JSON object per line) in submission order.
113	func queryAll(t *testing.T, state string) []cliFullRecord {
114		t.Helper()
115		r := queueCLI(t, state, "query")
116		if r.code != 0 {
117			t.Fatalf("query listing: exit=%d stderr=%q", r.code, r.stderr)
118		}
119		var out []cliFullRecord
120		dec := json.NewDecoder(strings.NewReader(r.stdout))
121		for {
122			var rec cliFullRecord
123			switch err := dec.Decode(&rec); err {
124			case nil:
125				out = append(out, rec)
126			case io.EOF:
127				return out
128			default:
129				t.Fatalf("decode query listing %q: %v", r.stdout, err)
130			}
131		}
132	}
133	
134	func recordIDs(recs []cliFullRecord) []string {
135		ids := make([]string, len(recs))
136		for i, r := range recs {
137			ids[i] = r.ID
138		}
139		return ids
140	}
141	
142	// assertSubmitMatchesQuery requires the submit echo and the single-record query
143	// to agree on every field both views expose.
144	func assertSubmitMatchesQuery(t *testing.T, sub cliSubmitRecord, q cliFullRecord) {
145		t.Helper()
146		if sub.ID != q.ID || sub.Status != q.Status || sub.Reason != q.Reason ||
147			sub.Attempts != q.Attempts || sub.NextRetry != q.NextRetry ||
148			sub.ExpiresAt != q.ExpiresAt {
149			t.Fatalf("submit output %+v disagrees with stored record %+v", sub, q)
150		}
151	}
152	
153	// assertContentConflict requires the exact CLI surface of a message-content
154	// conflict: exit 13, a stderr line naming both the id-conflict category and
155	// the differing content, the message id, and nothing on stdout.
156	func assertContentConflict(t *testing.T, r cliResult, id string) {
157		t.Helper()
158		if r.code != 13 {
159			t.Fatalf("want exit 13 for %s, got %d (stdout=%q stderr=%q)", id, r.code, r.stdout, r.stderr)
160		}
161		if r.stdout != "" {
162			t.Fatalf("a rejected submit must not print a success record: %q", r.stdout)
163		}
164		for _, want := range []string{"message id conflict", "different content", id} {
165			if !strings.Contains(r.stderr, want) {
166				t.Fatalf("stderr for %s missing %q:\n%s", id, want, r.stderr)
167			}
168		}
169	}
170	
171	// assertTerminalReject requires exit 14 naming the terminal category, the id
172	// and its current status; a terminal id must never be downgraded to a content
173	// conflict (13), even when the resubmitted content differs.
174	func assertTerminalReject(t *testing.T, r cliResult, id, status string) {
175		t.Helper()
176		if r.code != 14 {
177			t.Fatalf("want exit 14 for terminal %s, got %d (stdout=%q stderr=%q)", id, r.code, r.stdout, r.stderr)
178		}
179		if r.stdout != "" {
180			t.Fatalf("a rejected submit must not print a success record: %q", r.stdout)
181		}
182		for _, want := range []string{"terminal", id, status} {
183			if !strings.Contains(r.stderr, want) {
184				t.Fatalf("stderr for %s missing %q:\n%s", id, want, r.stderr)
185			}
186		}
187		if strings.Contains(r.stderr, "different content") {
188			t.Fatalf("terminal %s must be reported as terminal, not content conflict: %s", id, r.stderr)
189		}
190	}
191	
192	// First submission leaves the message pending; submitting byte-identical
193	// content again succeeds and echoes the same existing record, the listing still
194	// contains exactly one entry for that id, and the original submission position
195	// does not move relative to messages submitted around the duplicate.
196	func TestCLISubmitIdenticalPendingReturnsExistingRecord(t *testing.T) {
197		state := t.TempDir()
198		registerSource(t, state, "chain-a")
199		if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
200			t.Fatalf("store header: %v", r)
201		}
202	
203		spec := cliSubmitSpec{
204			id: "m1", from: "chain-a", to: "chain-b", nonce: 7,
205			proofAt: 90, payload: "hello", expiresAt: 9_000_000_000_000,
206		}
207		first, rawFirst := mustSubmit(t, state, spec)
208		wantFirst := cliSubmitRecord{
209			ID: "m1", Status: "pending", Reason: "awaiting first processing",
210			Attempts: 0, ExpiresAt: 9_000_000_000_000,
211		}
212		if first != wantFirst {
213			t.Fatalf("first submit output wrong: %+v", first)
214		}
215	
216		// A sibling after m1 but before the duplicate pins m1's seq position.
217		mustSubmit(t, state, cliSubmitSpec{
218			id: "sib-before", from: "chain-a", to: "chain-b", nonce: 10,
219			proofAt: 10, payload: "s1", expiresAt: 9_000_000_000_000,
220		})
221	
222		second, rawSecond := mustSubmit(t, state, spec)
223		if rawSecond != rawFirst || second != first {
224			t.Fatalf("identical resubmit must echo the same record:\nfirst =%q\nsecond=%q", rawFirst, rawSecond)
225		}
226	
227		mustSubmit(t, state, cliSubmitSpec{
228			id: "sib-after", from: "chain-a", to: "chain-b", nonce: 11,
229			proofAt: 10, payload: "s2", expiresAt: 9_000_000_000_000,
230		})
231	
232		stored := queryFull(t, state, "m1")
233		assertSubmitMatchesQuery(t, second, stored)
234		if stored.From != spec.from || stored.To != spec.to || stored.Nonce != spec.nonce ||
235			stored.Payload != spec.payload || stored.ProofAt != spec.proofAt ||
236			stored.ExpiresAt != spec.expiresAt {
237			t.Fatalf("stored content changed on identical resubmit: %+v", stored)
238		}
239	
240		all := queryAll(t, state)
241		if got := recordIDs(all); len(got) != 3 || got[0] != "m1" || got[1] != "sib-before" || got[2] != "sib-after" {
242			t.Fatalf("duplicate submit must not add an entry or move the original seq: %v", got)
243		}
244	}
245	
246	// Omitting --payload and --expires-at is the same message as passing "" and 0
247	// explicitly; the duplicate returns the existing record, the listing has one
248	// entry, and expiry 0 still means never (the message delivers on advance).
249	func TestCLISubmitOmittedPayloadAndExpiryEqualExplicitZero(t *testing.T) {
250		state := t.TempDir()
251		registerSource(t, state, "chain-a")
252		if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
253			t.Fatalf("store header: %v", r)
254		}
255	
256		omitted := cliSubmitSpec{
257			id: "d1", from: "chain-a", to: "chain-b", nonce: 1,
258			proofAt: 10, omitPayload: true, omitExpires: true,
259		}
260		first, rawFirst := mustSubmit(t, state, omitted)
261		if first.Status != "pending" || first.ExpiresAt != 0 || first.NextRetry != 0 || first.Attempts != 0 {
262			t.Fatalf("default submit output wrong: %+v", first)
263		}
264		if strings.Contains(rawFirst, "expiresAtMs") || strings.Contains(rawFirst, "nextRetryMs") {
265			t.Fatalf("zero expiry/no-retry fields must be omitted: %q", rawFirst)
266		}
267	
268		explicit := omitted
269		explicit.omitPayload, explicit.omitExpires = false, false
270		explicit.payload, explicit.expiresAt = "", 0
271		second, rawSecond := mustSubmit(t, state, explicit)
272		if rawSecond != rawFirst || second != first {
273			t.Fatalf("explicit empty payload/zero expiry must equal the defaults:\n%q\n%q", rawFirst, rawSecond)
274		}
275	
276		all := queryAll(t, state)
277		if len(all) != 1 || all[0].ID != "d1" || all[0].Payload != "" || all[0].ExpiresAt != 0 {
278			t.Fatalf("duplicate default submit must not add an entry: %+v", all)
279		}
280	
281		rep := advanceCLI(t, state, 1_700_000_000_000)
282		if got := resultFor(t, rep, "d1"); got.Status != "success" {
283			t.Fatalf("expiry 0 must mean never expire; message should deliver: %+v", got)
284		}
285	}
286	
287	// Once the first processing has parked a message in waiting (no trusted header
288	// at the proof height yet), an identical resubmit returns the CURRENT waiting
289	// record — status, reason, attempt count and next retry time — not a fresh
290	// pending echo. It must not process early, add an attempt or reschedule the
291	// retry, and the submit echo must match a single-id query exactly.
292	func TestCLISubmitIdenticalWaitingReturnsCurrentWaitingRecord(t *testing.T) {
293		state := t.TempDir()
294		registerSource(t, state, "chain-a")
295		if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
296			t.Fatalf("store header: %v", r)
297		}
298	
299		spec := cliSubmitSpec{
300			id: "w1", from: "chain-a", to: "chain-b", nonce: 8,
301			proofAt: 110, payload: "world", expiresAt: 9_000_000_000_000,
302		}
303		mustSubmit(t, state, spec)
304		rep := advanceCLI(t, state, 1_700_000_000_000)
305		if got := resultFor(t, rep, "w1"); got.Status != "waiting" {
306			t.Fatalf("setup: want waiting, got %+v", got)
307		}
308	
309		wantWaiting := cliSubmitRecord{
310			ID: "w1", Status: "waiting",
311			Reason:    "waiting for trusted header covering height 110 (current 100)",
312			Attempts:  1,
313			NextRetry: 1_700_000_001_000,
314			ExpiresAt: 9_000_000_000_000,
315		}
316		echo, rawEcho := mustSubmit(t, state, spec)
317		if echo != wantWaiting {
318			t.Fatalf("identical resubmit must return the current waiting record: %+v\n%s", echo, rawEcho)
319		}
320		assertSubmitMatchesQuery(t, echo, queryFull(t, state, "w1"))
321		if all := queryAll(t, state); len(all) != 1 || all[0].ID != "w1" {
322			t.Fatalf("waiting duplicate must not add a queue entry: %+v", all)
323		}
324	
325		// Advancing half a second early processes nothing; the duplicate submit
326		// must neither have advanced the clock nor rescheduled the retry.
327		early := advanceCLI(t, state, 1_700_000_000_500)
328		if len(early.Results) != 0 {
329			t.Fatalf("nothing is due before the retry instant: %+v", early.Results)
330		}
331		echo2, _ := mustSubmit(t, state, spec)
332		if echo2 != wantWaiting {
333			t.Fatalf("waiting record must keep status/reason/attempts/retry: %+v", echo2)
334		}
335		if got := queryFull(t, state, "w1"); got.Status != "waiting" ||
336			got.Reason != wantWaiting.Reason || got.Attempts != 1 ||
337			got.NextRetry != 1_700_000_001_000 {
338			t.Fatalf("stored waiting record changed: %+v", got)
339		}
340	}
341	
342	// Identity of content covers every field: source chain, destination chain,
343	// nonce, payload, proof height and absolute expiry. Changing any single one of
344	// them on a pending id must exit 13 as a content conflict and leave the
345	// original content and pending state stored, with no second entry.
346	func TestCLISubmitContentConflictExit13ForEveryField(t *testing.T) {
347		base := cliSubmitSpec{
348			id: "m", from: "chain-a", to: "chain-b", nonce: 7,
349			proofAt: 90, payload: "hello", expiresAt: 9_000_000_000_000,
350		}
351		cases := []struct {
352			name   string
353			mutate func(*cliSubmitSpec)
354		}{
355			{"source chain", func(s *cliSubmitSpec) { s.from = "chain-other" }},
356			{"destination chain", func(s *cliSubmitSpec) { s.to = "chain-c" }},
357			{"nonce", func(s *cliSubmitSpec) { s.nonce = 8 }},
358			{"payload", func(s *cliSubmitSpec) { s.payload = "HELLO" }},
359			{"proof height", func(s *cliSubmitSpec) { s.proofAt = 91 }},
360			{"absolute expiry", func(s *cliSubmitSpec) { s.expiresAt = 9_000_000_000_001 }},
361		}
362		for _, tc := range cases {
363			t.Run(tc.name, func(t *testing.T) {
364				state := t.TempDir()
365				mustSubmit(t, state, base)
366	
367				changed := base
368				tc.mutate(&changed)
369				assertContentConflict(t, submitRaw(t, state, changed), "m")
370	
371				got := queryFull(t, state, "m")
372				if got.From != base.from || got.To != base.to || got.Nonce != base.nonce ||
373					got.Payload != base.payload || got.ProofAt != base.proofAt ||
374					got.ExpiresAt != base.expiresAt {
375					t.Fatalf("conflicting submit overwrote original content: %+v", got)
376				}
377				if got.Status != "pending" || got.Reason != "awaiting first processing" ||
378					got.Attempts != 0 || got.NextRetry != 0 {
379					t.Fatalf("conflicting submit changed pending state: %+v", got)
380				}
381				if all := queryAll(t, state); len(all) != 1 || all[0].ID != "m" {
382					t.Fatalf("conflicting submit must not add an entry: %+v", all)
383				}
384			})
385		}
386	}
387	
388	// Changing just the proof height or just the expiry of a WAITING record is
389	// still a 13 conflict: the original content, status, reason, attempt count and
390	// scheduled retry all survive, an early advance still processes nothing, and
391	// the message later delivers against its ORIGINAL proof height (a trusted
392	// header at 110 covers the kept proof 110, not the rejected 111).
393	func TestCLISubmitWaitingConflictKeepsContentAndSchedule(t *testing.T) {
394		state := t.TempDir()
395		registerSource(t, state, "chain-a")
396		if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
397			t.Fatalf("store header: %v", r)
398		}
399		spec := cliSubmitSpec{
400			id: "w", from: "chain-a", to: "chain-b", nonce: 5,
401			proofAt: 110, payload: "orig", expiresAt: 9_000_000_000_000,
402		}
403		mustSubmit(t, state, spec)
404		advanceCLI(t, state, 1_700_000_000_000)
405		before := queryFull(t, state, "w")
406		if before.Status != "waiting" || before.Attempts != 1 || before.NextRetry != 1_700_000_001_000 {
407			t.Fatalf("setup waiting record wrong: %+v", before)
408		}
409	
410		mutations := []struct {
411			name   string
412			mutate func(*cliSubmitSpec)
413		}{
414			{"proof height only", func(s *cliSubmitSpec) { s.proofAt = 111 }},
415			{"expiry only", func(s *cliSubmitSpec) { s.expiresAt = 9_000_000_000_001 }},
416			{"payload only", func(s *cliSubmitSpec) { s.payload = "changed" }},
417			{"nonce only", func(s *cliSubmitSpec) { s.nonce = 6 }},
418			{"destination only", func(s *cliSubmitSpec) { s.to = "chain-c" }},
419		}
420		for _, tc := range mutations {
421			t.Run(tc.name, func(t *testing.T) {
422				changed := spec
423				tc.mutate(&changed)
424				assertContentConflict(t, submitRaw(t, state, changed), "w")
425				if got := queryFull(t, state, "w"); got != before {
426					t.Fatalf("waiting record changed after rejected submit:\nbefore=%+v\nafter =%+v", before, got)
427				}
428			})
429		}
430	
431		early := advanceCLI(t, state, 1_700_000_000_500)
432		if len(early.Results) != 0 {
433			t.Fatalf("rejected submits must not reschedule or trigger processing: %+v", early.Results)
434		}
435		if got := queryFull(t, state, "w"); got != before {
436			t.Fatalf("waiting record changed on early advance: %+v", got)
437		}
438	
439		// Trusted 110 covers the original proof height 110; the rejected 111 would
440		// still wait. Success at the scheduled retry proves the original content
441		// was kept and never processed early.
442		if r := storeHeader(t, state, "chain-a", 110, "0x110", true); r.code != 0 {
443			t.Fatalf("extend coverage: %v", r)
444		}
445		rep := advanceCLI(t, state, 1_700_000_001_000)
446		got := resultFor(t, rep, "w")
447		if got.Status != "success" ||
448			got.Reason != "delivered; proof verified by trusted header at height 110" {
449			t.Fatalf("message must deliver by its original proof height 110: %+v", got)
450		}
451	}
452	
453	// A rejected submit changes neither the target message nor any other message
454	// in the same directory: sibling content stays intact and the first-submission
455	// order of all three ids is unchanged when they are later processed.
456	func TestCLISubmitConflictLeavesSiblingsAndOrderUntouched(t *testing.T) {
457		state := t.TempDir()
458		registerSource(t, state, "chain-a")
459		if r := storeHeader(t, state, "chain-a", 200, "0x200", true); r.code != 0 {
460			t.Fatalf("store header: %v", r)
461		}
462	
463		a := cliSubmitSpec{id: "a1", from: "chain-a", to: "chain-b", nonce: 1, proofAt: 10, payload: "pa", expiresAt: 9_000_000_000_000}
464		m := cliSubmitSpec{id: "mid", from: "chain-a", to: "chain-b", nonce: 5, proofAt: 100, payload: "original", expiresAt: 9_000_000_000_000}
465		b := cliSubmitSpec{id: "b1", from: "chain-a", to: "chain-b", nonce: 9, proofAt: 200, payload: "pb", expiresAt: 9_000_000_000_000}
466		mustSubmit(t, state, a)
467		mustSubmit(t, state, m)
468		mustSubmit(t, state, b)
469	
470		badProof := m
471		badProof.proofAt = 101
472		assertContentConflict(t, submitRaw(t, state, badProof), "mid")
473		badPayload := m
474		badPayload.payload = "changed"
475		assertContentConflict(t, submitRaw(t, state, badPayload), "mid")
476	
477		all := queryAll(t, state)
478		if got := recordIDs(all); len(got) != 3 || got[0] != "a1" || got[1] != "mid" || got[2] != "b1" {
479			t.Fatalf("order/content must survive rejected submits: %v", got)
480		}
481		got := map[string]cliFullRecord{}
482		for _, r := range all {
483			got[r.ID] = r
484		}
485		if got["mid"].ProofAt != 100 || got["mid"].Payload != "original" {
486			t.Fatalf("target content overwritten: %+v", got["mid"])
487		}
488		if got["a1"].ProofAt != 10 || got["a1"].Payload != "pa" ||
489			got["b1"].ProofAt != 200 || got["b1"].Payload != "pb" {
490			t.Fatalf("sibling content changed: a1=%+v b1=%+v", got["a1"], got["b1"])
491		}
492	
493		// All three process in original submission order using their original content.
494		rep := advanceCLI(t, state, 1_700_000_000_000)
495		if len(rep.Results) != 3 {
496			t.Fatalf("want 3 delivery results, got %+v", rep.Results)
497		}
498		for i, wantID := range []string{"a1", "mid", "b1"} {
499			if rep.Results[i].ID != wantID || rep.Results[i].Status != "success" {
500				t.Fatalf("position %d: want %s success, got %+v", i, wantID, rep.Results[i])
501			}
502		}
503	}
504	
505	// After a message is delivered its id is dead: resubmitting identical content
506	// or content differing in any single field both exit 14 (never 13), print no
507	// record, and the stored success with its reason is still queryable. Updating
508	// the trusted header and advancing again does not deliver the message a second
509	// time.
510	func TestCLISubmitDeliveredIDAlwaysRejectedWith14(t *testing.T) {
511		state := t.TempDir()
512		registerSource(t, state, "chain-a")
513		if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
514			t.Fatalf("store header: %v", r)
515		}
516		spec := cliSubmitSpec{
517			id: "s", from: "chain-a", to: "chain-b", nonce: 7,
518			proofAt: 90, payload: "hello", expiresAt: 9_000_000_000_000,
519		}
520		mustSubmit(t, state, spec)
521		rep := advanceCLI(t, state, 1_700_000_000_000)
522		if got := resultFor(t, rep, "s"); got.Status != "success" ||
523			got.Reason != "delivered; proof verified by trusted header at height 100" {
524			t.Fatalf("setup delivery wrong: %+v", got)
525		}
526		before := queryFull(t, state, "s")
527	
528		// Identical content: terminal, not an idempotent success echo.
529		assertTerminalReject(t, submitRaw(t, state, spec), "s", "success")
530	
531		// Different content in any field is still 14, never a 13 content conflict.
532		for _, tc := range []struct {
533			name   string
534			mutate func(*cliSubmitSpec)
535		}{
536			{"proof height", func(s *cliSubmitSpec) { s.proofAt = 91 }},
537			{"payload", func(s *cliSubmitSpec) { s.payload = "x" }},
538			{"expiry", func(s *cliSubmitSpec) { s.expiresAt = 9_000_000_000_001 }},
539			{"nonce", func(s *cliSubmitSpec) { s.nonce = 8 }},
540			{"source", func(s *cliSubmitSpec) { s.from = "chain-a2" }},
541			{"destination", func(s *cliSubmitSpec) { s.to = "chain-c" }},
542		} {
543			t.Run(tc.name, func(t *testing.T) {
544				changed := spec
545				tc.mutate(&changed)
546				assertTerminalReject(t, submitRaw(t, state, changed), "s", "success")
547			})
548		}
549	
550		if got := queryFull(t, state, "s"); got != before {
551			t.Fatalf("success record changed after rejected resubmits:\nbefore=%+v\nafter =%+v", before, got)
552		}
553		if all := queryAll(t, state); len(all) != 1 || all[0].ID != "s" {
554			t.Fatalf("rejected resubmit must not add an entry: %+v", all)
555		}
556	
557		// A higher trusted header and another advance must not resurrect or
558		// redeliver the terminal message.
559		if r := storeHeader(t, state, "chain-a", 120, "0x120", true); r.code != 0 {
560			t.Fatalf("extend coverage: %v", r)
561		}
562		again := advanceCLI(t, state, 1_700_000_100_000)
563		if len(again.Results) != 0 {
564			t.Fatalf("delivered message must not reappear on later advances: %+v", again.Results)
565		}
566		if got := queryFull(t, state, "s"); got != before {
567			t.Fatalf("success record changed after re-advance:\nbefore=%+v\nafter =%+v", before, got)
568		}
569	}
570	
571	// Every terminal status, not just success, permanently rejects the id with 14
572	// for identical and differing content alike, while the stored status and reason
573	// stay queryable and unchanged.
574	func TestCLISubmitTerminalIDsRejectedWith14AcrossStatuses(t *testing.T) {
575		t.Run("expired", func(t *testing.T) {
576			state := t.TempDir()
577			registerSource(t, state, "chain-a")
578			spec := cliSubmitSpec{
579				id: "e", from: "chain-a", to: "chain-b", nonce: 1,
580				proofAt: 100, payload: "p", expiresAt: 1000,
581			}
582			mustSubmit(t, state, spec)
583			rep := advanceCLI(t, state, 1000) // now == expiry counts as expired
584			if got := resultFor(t, rep, "e"); got.Status != "expired" {
585				t.Fatalf("setup: want expired, got %+v", got)
586			}
587			before := queryFull(t, state, "e")
588			assertTerminalReject(t, submitRaw(t, state, spec), "e", "expired")
589			changed := spec
590			changed.proofAt = 101
591			assertTerminalReject(t, submitRaw(t, state, changed), "e", "expired")
592			if got := queryFull(t, state, "e"); got != before {
593				t.Fatalf("expired record changed: %+v", got)
594			}
595		})
596	
597		t.Run("unknown-source", func(t *testing.T) {
598			state := t.TempDir()
599			spec := cliSubmitSpec{
600				id: "u", from: "chain-ghost", to: "chain-b", nonce: 1,
601				proofAt: 10, payload: "p", expiresAt: 9_000_000_000_000,
602			}
603			mustSubmit(t, state, spec)
604			rep := advanceCLI(t, state, 1000)
605			if got := resultFor(t, rep, "u"); got.Status != "unknown-source" {
606				t.Fatalf("setup: want unknown-source, got %+v", got)
607			}
608			before := queryFull(t, state, "u")
609			assertTerminalReject(t, submitRaw(t, state, spec), "u", "unknown-source")
610			changed := spec
611			changed.payload = "different"
612			assertTerminalReject(t, submitRaw(t, state, changed), "u", "unknown-source")
613			if got := queryFull(t, state, "u"); got != before {
614				t.Fatalf("unknown-source record changed: %+v", got)
615			}
616		})
617	
618		t.Run("replay", func(t *testing.T) {
619			state := t.TempDir()
620			registerSource(t, state, "chain-a")
621			if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
622				t.Fatalf("store header: %v", r)
623			}
624			winner := cliSubmitSpec{
625				id: "win", from: "chain-a", to: "chain-b", nonce: 3,
626				proofAt: 10, payload: "w", expiresAt: 9_000_000_000_000,
627			}
628			loser := cliSubmitSpec{
629				id: "lose", from: "chain-a", to: "chain-b", nonce: 3,
630				proofAt: 10, payload: "l", expiresAt: 9_000_000_000_000,
631			}
632			mustSubmit(t, state, winner)
633			mustSubmit(t, state, loser)
634			rep := advanceCLI(t, state, 1000)
635			if got := resultFor(t, rep, "lose"); got.Status != "replay" {
636				t.Fatalf("setup: want replay, got %+v", got)
637			}
638			before := queryFull(t, state, "lose")
639			assertTerminalReject(t, submitRaw(t, state, loser), "lose", "replay")
640			changed := loser
641			changed.payload = "changed"
642			assertTerminalReject(t, submitRaw(t, state, changed), "lose", "replay")
643			if got := queryFull(t, state, "lose"); got != before {
644				t.Fatalf("replay record changed: %+v", got)
645			}
646		})
647	}
