	bad = append(bad, 0, 0, 0, 0)
	binary.BigEndian.PutUint32(bad[pos:], 4294967295)
	bad = append(bad, raw[pos+frameHeaderSize:]...)
	writeRawLog(t, dir, bad)

	if _, err := Open(dir); !errors.Is(err, ErrCorrupt) {
